@@ -0,0 +1,167 @@
+/*
+    SPDX-FileCopyrightText: 2026 Niccolò Venerandi <niccolo@venerandi.com>
+
+    SPDX-License-Identifier: GPL-2.0-or-later
+*/
+
+#include "wallpaperalbums.h"
+
+#include <QDir>
+#include <QQmlEngine>
+#include <QUrl>
+#include <QUuid>
+
+#include <KConfigGroup>
+
+using namespace Qt::StringLiterals;
+
+static constexpr QLatin1StringView s_groupName = "Wallpaper Albums"_L1;
+
+WallpaperAlbums *WallpaperAlbums::instance()
+{
+    static WallpaperAlbums *const albums = [] {
+        auto albums = new WallpaperAlbums;
+        QQmlEngine::setObjectOwnership(albums, QQmlEngine::CppOwnership);
+        return albums;
+    }();
+    return albums;
+}
+
+WallpaperAlbums::WallpaperAlbums(QObject *parent)
+    : QObject(parent)
+    , m_config(KSharedConfig::openConfig(u"plasmarc"_s))
+    , m_watcher(KConfigWatcher::create(m_config))
+{
+    load();
+
+    connect(m_watcher.data(), &KConfigWatcher::configChanged, this, [this](const KConfigGroup &group) {
+        if (group.name() == s_groupName || group.parent().name() == s_groupName) {
+            load();
+        }
+    });
+}
+
+void WallpaperAlbums::load()
+{
+    const KConfigGroup group = m_config->group(s_groupName);
+
+    QList<Album> albums;
+    const QStringList ids = group.groupList();
+    for (const QString &id : ids) {
+        const KConfigGroup albumGroup = group.group(id);
+        const QString name = albumGroup.readEntry("Name", QString());
+        if (!name.isEmpty()) {
+            albums.append({id, name, albumGroup.readEntry("Images", QStringList())});
+        }
+    }
+    std::sort(albums.begin(), albums.end(), [](const Album &a, const Album &b) {
+        return QString::localeAwareCompare(a.name, b.name) < 0;
+    });
+
+    if (albums != m_albums) {
+        m_albums = albums;
+        Q_EMIT albumsChanged();
+    }
+}
+
+void WallpaperAlbums::save(const Album &album)
+{
+    KConfigGroup group = m_config->group(s_groupName).group(album.id);
+    group.writeEntry("Name", album.name, KConfig::Notify);
+    group.writeEntry("Images", album.images, KConfig::Notify);
+    m_config->sync();
+}
+
+WallpaperAlbums::Album *WallpaperAlbums::find(const QString &id)
+{
+    const auto it = std::ranges::find(m_albums, id, &Album::id);
+    return it == m_albums.end() ? nullptr : &*it;
+}
+
+const WallpaperAlbums::Album *WallpaperAlbums::find(const QString &id) const
+{
+    const auto it = std::ranges::find(m_albums, id, &Album::id);
+    return it == m_albums.cend() ? nullptr : &*it;
+}
+
+QVariantList WallpaperAlbums::albums() const
+{
+    QVariantList albums;
+    albums.reserve(m_albums.size());
+    for (const Album &album : m_albums) {
+        albums.append(QVariantMap{{u"id"_s, album.id}, {u"name"_s, album.name}});
+    }
+    return albums;
+}
+
+bool WallpaperAlbums::hasAlbum(const QString &id) const
+{
+    return find(id);
+}
+
+QSet<QString> WallpaperAlbums::images(const QString &id) const
+{
+    const Album *album = find(id);
+    return album ? QSet<QString>(album->images.cbegin(), album->images.cend()) : QSet<QString>();
+}
+
+QString WallpaperAlbums::createAlbum(const QString &name)
+{
+    const QString trimmedName = name.trimmed();
+    if (trimmedName.isEmpty()) {
+        return QString();
+    }
+
+    for (const Album &album : std::as_const(m_albums)) {
+        if (album.name.compare(trimmedName, Qt::CaseInsensitive) == 0) {
+            return album.id;
+        }
+    }
+
+    const Album album{QUuid::createUuid().toString(QUuid::WithoutBraces), trimmedName, {}};
+    save(album);
+    load();
+    return album.id;
+}
+
+void WallpaperAlbums::removeAlbum(const QString &id)
+{
+    if (!find(id)) {
+        return;
+    }
+
+    m_config->group(s_groupName).group(id).deleteGroup(KConfig::Notify);
+    m_config->sync();
+    load();
+}
+
+bool WallpaperAlbums::contains(const QString &id, const QString &image) const
+{
+    const Album *album = find(id);
+    return album && album->images.contains(imagePath(image));
+}
+
+void WallpaperAlbums::setInAlbum(const QString &id, const QString &image, bool inAlbum)
+{
+    Album *album = find(id);
+    const QString path = imagePath(image);
+    if (!album || path.isEmpty() || album->images.contains(path) == inAlbum) {
+        return;
+    }
+
+    if (inAlbum) {
+        album->images.append(path);
+    } else {
+        album->images.removeAll(path);
+    }
+    save(*album);
+    Q_EMIT albumsChanged();
+}
+
+QString WallpaperAlbums::imagePath(const QString &image)
+{
+    if (image.isEmpty()) {
+        return QString();
+    }
+    return QDir::cleanPath(QUrl::fromUserInput(image).toLocalFile());
+}
